#!/usr/bin/env python3
"""enzyme/alphafold-plddt-analyzer — auto-generated run.py (archetype=structure_predict).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "structure_predict"
BRAIN = "enzyme"
SKILL = "alphafold-plddt-analyzer"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'alphafold-plddt-analyzer', 'sequence': '', 'model_path': '', 'plddt_mean': 0.0, 'ptm': 0.0, 'n_residues': 0, 'runtime_sec': 0.0, 'diagnostics': {'brain': 'enzyme', 'archetype': 'structure_predict'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """AlphaFold/ESMFold PDB pLDDT 解析:B-factor 字段就是 pLDDT。
    输入:input_pdb / regions(optional list of [start,end])
    输出:global_plddt_stats / active_site_check / regions[]
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pdb = payload.get("input_pdb") or payload.get("structure_pdb")
    regions = payload.get("regions") or []
    active_site = payload.get("active_site_residues") or []
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "Biopython", "n_regions": len(regions)}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "sequence": "", "model_path": pdb or "",
                "plddt_mean": 0.0, "ptm": 0.0, "n_residues": 0,
                "diagnostics": {**diagnostics, "dry": True}}
    if not pdb or not _os.path.isfile(pdb):
        return {"ok": False, "error": "需要 input_pdb", "diagnostics": diagnostics}
    script = (
        "import json, sys, statistics\n"
        "from Bio.PDB import PDBParser\n"
        f"pdb = {pdb!r}; regions = {regions!r}; active = {active_site!r}\n"
        "parser = PDBParser(QUIET=True)\n"
        "struct = parser.get_structure('s', pdb)\n"
        "per_res = []  # (chain, resnum, plddt)\n"
        "for atom in struct.get_atoms():\n"
        "    if atom.get_name() != 'CA': continue\n"
        "    res = atom.get_parent(); chain = res.get_parent().id\n"
        "    if res.get_id()[0].strip(): continue\n"
        "    per_res.append((chain, res.get_id()[1], float(atom.get_bfactor())))\n"
        "vals = [v for _,_,v in per_res]\n"
        "if not vals: print(json.dumps({'__err':'no_ca_atoms'})); sys.exit(1)\n"
        "stats = {'mean': statistics.mean(vals), 'median': statistics.median(vals),\n"
        "         'fraction_high': sum(1 for v in vals if v >= 90)/len(vals),\n"
        "         'fraction_confident': sum(1 for v in vals if v >= 70)/len(vals),\n"
        "         'fraction_low': sum(1 for v in vals if v < 50)/len(vals)}\n"
        "active_vals = [v for _,r,v in per_res if r in active]\n"
        "active_check = {'residues_checked': active,\n"
        "                 'min_plddt_at_active_site': min(active_vals) if active_vals else None,\n"
        "                 'verdict': 'PASS' if (active_vals and min(active_vals) >= 70) else ('FAIL' if active_vals else 'SKIP')}\n"
        "reg_out = []\n"
        "for s,e in regions:\n"
        "    vv = [v for _,r,v in per_res if s <= r <= e]\n"
        "    if vv: reg_out.append({'start': s, 'end': e, 'plddt_mean': statistics.mean(vv),\n"
        "                          'category': 'high' if statistics.mean(vv)>=90 else ('confident' if statistics.mean(vv)>=70 else 'low')})\n"
        "out = {'n_residues': len(vals), 'plddt_mean': stats['mean'],\n"
        "       'global_plddt_stats': stats, 'active_site_check': active_check,\n"
        "       'regions': reg_out}\n"
        "json.dump(out, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "plddt 解析失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, "sequence": "", "model_path": pdb,
            "plddt_mean": parsed.get("plddt_mean", 0.0), "ptm": 0.0,
            "n_residues": parsed.get("n_residues", 0),
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
